import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

# Build lookup: project_name -> framework -> package -> resolvedVersion
def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        lookup[name] = {}
        for fw in proj['frameworks']:
            lookup[name][fw['framework']] = {}
            for pkg in fw['topLevelPackages']:
                lookup[name][fw['framework']][pkg['id']] = pkg['resolvedVersion']
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

changes = []
unchanged = []

for proj in sorted(set(list(b.keys()) + list(a.keys()))):
    for fw in sorted(set(list(b.get(proj, {}).keys()) + list(a.get(proj, {}).keys()))):
        b_pkgs = b.get(proj, {}).get(fw, {})
        a_pkgs = a.get(proj, {}).get(fw, {})
        for pkg in sorted(set(list(b_pkgs.keys()) + list(a_pkgs.keys()))):
            bv = b_pkgs.get(pkg)
            av = a_pkgs.get(pkg)
            if bv and av and bv == av:
                unchanged.append((proj, fw, pkg, av))
            elif bv and av and bv != av:
                changes.append((proj, fw, pkg, bv, av, 'Aligned to highest version'))
            elif bv and not av:
                changes.append((proj, fw, pkg, bv, '-', 'Removed'))
            elif not bv and av:
                changes.append((proj, fw, pkg, '-', av, 'Added'))

print('=== CHANGES ===')
if changes:
    for c in changes:
        print(f'{c[0]} | {c[1]} | {c[2]} | {c[3]} -> {c[4]} | {c[5]}')
else:
    print('None')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'{u[0]} | {u[1]} | {u[2]} | {u[3]}')
"

